55	function browserKey(event: KeyboardEvent): Key | null {
56	  switch (event.key) {
57	    case "ArrowUp": return "up";
58	    case "ArrowDown": return "down";
59	    case "ArrowLeft": return "left";
60	    case "ArrowRight": return "right";
61	    case "Enter": return "enter";
62	    case "Backspace": return "backspace";
63	  }
64	  if (event.key.length !== 1) return null;
65	  const lower = event.key.toLowerCase();
66	  if (lower === "w") return "up";
67	  if (lower === "s") return "down";
68	  if (lower === "a") return "left";
69	  if (lower === "d") return "right";
70	  if (lower === "q") return "quit";
71	  return { char: event.key };
72	}
