713	    const target = (event.target as HTMLElement).closest<HTMLButtonElement>("[data-order-id]");
714	    if (!target || target.hasAttribute("data-already-high")) return;
715	    submitIntervention({ kind: "priority", targetRole: interveneRole, orderId: target.dataset.orderId!, priority: "high" });
716	  });
717	  els.approve?.addEventListener("click", (event) => {
718	    const target = (event.target as HTMLElement).closest<HTMLButtonElement>("[data-decision-id]");
719	    if (!target?.dataset.decisionId || !target.dataset.optionId) return;
720	    submitIntervention({
721	      kind: "approve",
722	      targetRole: (target.dataset.speakerRole as PlayerInterventionInput["targetRole"]) ?? interveneRole,
723	      decisionId: target.dataset.decisionId,
724	      optionId: target.dataset.optionId,
725	    });
726	  });
727	}
