908	/**
909	 * The evidence receipt: what the shift actually recorded, counted off the
910	 * run's own journal — the same events `Export Trace` writes out as
911	 * restaurant-arena-trace/v3.
912	 *
913	 * Split by who authored each event, because that split is the whole point of
914	 * the export: what the house did on its own (`system`) has to stay separable
915	 * from what the manager handed over (`player`) and what the workers did with
916	 * it. Every number here is counted, never estimated, and nothing is
917	 * attributed to a model that did not stamp the event itself.
918	 */
919	function getArenaEvidenceHtml(): string {
920	  if (!game || game.name !== "restaurant-arena") return "";
921	  const journal = game as unknown as { getRecordedEvents?: () => { actorId?: string; model?: unknown; toolResult?: { ok?: boolean } | null }[] };
922	  if (typeof journal.getRecordedEvents !== "function") return "";
923	  let events: { actorId?: string; model?: unknown; toolResult?: { ok?: boolean } | null }[];
924	  try {
925	    events = journal.getRecordedEvents();
926	  } catch (err) {
927	    console.error("Failed to read the arena event journal:", err);
928	    return "";
929	  }
930	  const system = events.filter((event) => event.actorId === "system").length;
931	  const manager = events.filter((event) => event.actorId === "player").length;
932	  const worker = events.length - system - manager;
933	  const rejected = events.filter((event) => event.toolResult?.ok === false).length;
934	  const modelStamped = events.filter((event) => event.model !== undefined && event.model !== null).length;
935	  // Only the authorship split gets tiles — that split is what the export is
936	  // for. The rest is one line, because a six-tile grid made a footnote look
937	  // like a scoreboard.
938	  const rows: [string, string][] = [
939	    ["System", `${system}`],
940	    ["Your handover", `${manager}`],
941	    ["Worker turns", `${worker}`],
942	  ];
943	  return `
944	    <div class="arena-evidence">
945	      <p class="debrief-criteria">${events.length} recorded events · exported by <code>Export Trace</code></p>
946	      <div class="evidence-stats">${rows
947	        .map(([label, value]) => `<span class="evidence-stat"><small>${escapeHtml(label)}</small><strong>${escapeHtml(value)}</strong></span>`)
948	        .join("")}</div>
949	      <p class="debrief-caveat">${rejected} rejected call${rejected === 1 ? "" : "s"} · ${modelStamped} stamped by a model. Counted from this run&rsquo;s journal, never inferred.</p>
950	    </div>`;
951	}
