fn append_local_score(score: LocalScoreInput) -> Result<LocalScoreEntry, String> {
    let path = tui_gamepigeon_dir()
        .ok_or_else(|| "Could not resolve home directory.".to_string())?
        .join("scores")
        .join("history.jsonl");
