      /* Collapsed mode swaps the whole arcade for a palm-sized console
         silhouette: d-pad, screen, A/B buttons. Drag it anywhere; click to
         reopen. The window itself is transparent, so only the pill shows. */
      body[data-mode="pill"] .app,
      body[data-mode="pill"] #return-prompt,
      body[data-mode="pill"] #how-to-play,
      body[data-mode="pill"] #signout-prompt { display: none !important; }
      body:not([data-mode="pill"]) .pill { display: none !important; }

      .pill {
        position: fixed;
        inset: 0;
        display: flex;
        align-items: center;
        gap: 7px;
        padding: 7px 9px;
        margin: 0;
        border: 2px solid transparent;
        border-radius: 22px;
        background:
          linear-gradient(180deg, #1c2028, #0b0d12) padding-box,
          conic-gradient(from 90deg, #ff5b5b, #ffbf4f, #f7ef61, #5cd888, #55a8ff, #a878ff, #ff70bc, #ff5b5b) border-box;
        box-shadow: inset 0 1px 0 rgba(255, 255, 255, .07);
        color: #e6eaf2;
        cursor: grab;
        -webkit-app-region: drag;
      }
      .pill:active { cursor: grabbing; }
      .pill:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

      /* D-pad: one horizontal bar crossed by one vertical bar. */
      .pill-dpad {
        position: relative;
        flex: 0 0 auto;
        width: 18px;
        height: 18px;
      }
      .pill-dpad::before, .pill-dpad::after {
        content: "";
        position: absolute;
        background: #39404e;
        border-radius: 2px;
        box-shadow: inset 0 1px 0 rgba(255, 255, 255, .08);
      }
      .pill-dpad::before { inset: 6px 0; }
      .pill-dpad::after { inset: 0 6px; }

      /* The little LCD — idle label swaps to "START" on hover. */
      .pill-screen {
        position: relative;
        flex: 1 1 auto;
        min-width: 0;
        height: 26px;
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 0 6px;
        border: 1px solid #000;
        border-radius: 5px;
        background: repeating-linear-gradient(0deg, rgba(255, 255, 255, .06) 0 1px, transparent 1px 3px), #05070a;
        box-shadow: inset 0 1px 3px rgba(0, 0, 0, .8);
        overflow: hidden;
        transition: background .25s ease, box-shadow .25s ease;
      }
      .pill:hover .pill-screen {
        background: repeating-linear-gradient(0deg, rgba(15, 23, 42, .08) 0 1px, transparent 1px 3px), var(--banana);
        box-shadow: inset 0 1px 2px rgba(15, 23, 42, .12);
      }

      .pill-label {
        position: absolute;
        max-width: calc(100% - 16px);
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
        font: 600 10px/1 var(--mono);
        letter-spacing: .12em;
        text-transform: uppercase;
        transition: opacity .22s ease;
      }
      .pill-label-idle { color: var(--banana); opacity: 1; }
      .pill-label-hint {
        color: var(--ink);
        opacity: 0;
        letter-spacing: .18em;
      }
      .pill:hover .pill-label-idle { opacity: 0; }
      .pill:hover .pill-label-hint { opacity: 1; }

      /* A/B buttons, offset the way they sit on a real handheld. */
      .pill-buttons {
        flex: 0 0 auto;
        display: flex;
        align-items: center;
        gap: 4px;
        padding-bottom: 4px;
      }
      .pill-buttons i {
        position: relative;
        width: 9px;
        height: 9px;
        border-radius: 50%;
        box-shadow: inset 0 -1px 1px rgba(0, 0, 0, .4);
        transition: transform .32s cubic-bezier(.34, 1.45, .64, 1), box-shadow .32s ease;
      }
      .pill-buttons i:first-child { background: var(--cinnabar-deep); transform: translateY(5px); }
      .pill-btn-a {
        background: var(--pumpkin-deep);
        transform: translateY(0);
      }
      .pill:hover .pill-btn-a {
        transform: translateY(-2px) scale(1.55);
        box-shadow: 0 3px 8px rgba(59, 178, 115, .4), inset 0 -1px 1px rgba(0, 0, 0, .35);
      }
      .pill-btn-a::after {
        content: "A";
        position: absolute;
        inset: -7px;
        display: grid;
        place-items: center;
        font: 700 7px/1 var(--sans);
        color: rgba(255, 255, 255, .92);
        opacity: 0;
        transform: scale(.4);
        transition: opacity .2s ease, transform .32s cubic-bezier(.34, 1.45, .64, 1);
        pointer-events: none;
        text-shadow: 0 1px 2px rgba(0, 0, 0, .5);
      }
      .pill:hover .pill-btn-a::after {
        opacity: 1;
        transform: scale(1);
      }

