1	/**
2	 * The manager brief: the one band of the screen that answers, in order,
3	 * "what am I trying to do tonight", "how close am I", and "what is the one
4	 * thing I should do right now".
5	 *
6	 * The arena already carries every fact this needs — the shift goal, the
7	 * running tally, the open decision, the live incident, the queue at the
8	 * door. What it never did was say any of it in one place, so a first-time
9	 * player had to reconstruct the state of the night from a ticket rail, a
10	 * star row and a scrolling log. This is a pure projection of the state the
11	 * scene already has: it invents no numbers and reads no metric the engine
12	 * does not actually keep.
13	 *
14	 * Deliberately thin. An earlier pass put the target sentence, five chips
15	 * and a full-sentence directive in the same band, which restated the same
16	 * numbers twice and gave a calm shift as much ink as a failing one. What
17	 * survives is only what changes a decision: the three conditions that can
18	 * lose the night, and one short instruction.
19	 *
20	 * Deliberately absent: any table-wait figure. The only wait the engine can
21	 * currently produce is `tableWaitMinutes`, which returns the whole-shift
22	 * clock rather than a per-table arrival delta, so putting it on screen
23	 * would claim a metric the data does not support (#304).
24	 */
25	
26	export type BriefTone = "ok" | "warn" | "bad";
27	
28	export interface BriefChip {
29	  readonly label: string;
30	  readonly value: string;
31	  readonly tone: BriefTone;
32	}
33	
34	export interface ArenaBrief {
35	  readonly chips: readonly BriefChip[];
36	  /** Short tag for the current directive — "DECIDE", "FIX", "STEP 2/4". */
37	  readonly nowLabel: string;
38	  /** The current issue and the action that answers it, in one sentence. */
39	  readonly now: string;
40	  /** What the last answered decision actually did, kept until the next one. */
41	  readonly last?: string;
42	}
43	
44	/** Everything `arenaBrief` reads. A structural subset of the scene state. */
45	export interface BriefInput {
46	  readonly clock?: { minute: number };
47	  readonly orders: readonly {
48	    id: string;
49	    tableId?: string;
50	    status: string;
51	    allergy?: string;
52	    priority: string;
