/** A logical (DPI-independent) frame size, in the units Tauri calls logical. */
export interface OverlaySize {
  readonly width: number;
  readonly height: number;
}

/**
 * The four frames the overlay ever takes. The browser preview mirrors these
 * pixel for pixel, and README's "Window sizes" table is these values — keep
 * the three in step.
 */
export const COMPACT_SIZE: OverlaySize = { width: 600, height: 850 };
export const EXPANDED_SIZE: OverlaySize = { width: 830, height: 900 };
export const PILL_SIZE: OverlaySize = { width: 144, height: 48 };
/** The floor's minimum. The pill is deliberately below it; nothing else is. */
export const MIN_SIZE: OverlaySize = { width: 500, height: 700 };

export type WindowSizeMode = "compact" | "expanded";

/** The frame the floor takes for a size preference, never below {@link MIN_SIZE}. */
export function floorSize(mode: WindowSizeMode): OverlaySize {
  const target = mode === "expanded" ? EXPANDED_SIZE : COMPACT_SIZE;
  return {
    width: Math.max(target.width, MIN_SIZE.width),
    height: Math.max(target.height, MIN_SIZE.height),
  };
}

