/**
 * Writes the one active-game record, replacing whatever was there.
 *
 * A run longer than {@link MAX_ACTIONS} stops extending the record rather than
 * replacing it with something `loadSavedGame` would reject: what is already
 * stored is a valid prefix of this same seeded run, so the next launch still
 * resumes — just a little earlier than the player left off.
 */
export function saveGame(saved: SavedGame, storage: Storage = localStorage): void {
  if (saved.actions.length > MAX_ACTIONS) return;
  try {
    storage.setItem(STORAGE_KEY, JSON.stringify(saved));
  } catch {
    // A full or blocked store must never interrupt the run it is describing.
  }
}

/** Drops the record entirely — a restart replaces the run, it doesn't continue it. */
export function clearSavedGame(storage: Storage = localStorage): void {
  try {
    storage.removeItem(STORAGE_KEY);
  } catch {
    // Same: losing the save is survivable, throwing mid-run is not.
  }
}

/** Rebuild only actions that remain accepted by this version of the game. */

