/**
 * When the overlay stops a shift by itself, and what it says while stopped.
 *
 * Split out of app.ts because the interesting part is a decision rather than a
 * repaint. The host's `Stop` hook fires `gamepigeon:pause` at every turn
 * boundary — with or without a run on screen, with or without the player
 * having asked for that behaviour — so "did the agent stop" and "should the
 * player be interrupted" are two different questions.
 *
 * Nothing in here touches the DOM or the engine: pausing is a state, and the
 * two things that read it (the timer that advances the shift, and the paused
 * card) both derive from that state.
 */

/**
 * Why the shift is stopped.
 *
 * - `agent-stop`: the harness reported the agent needs the player. This is the
 *   only trigger that puts a card on screen.
 * - `minimized`: the floor was collapsed to the pill. A shift the player
 *   cannot see must not keep running, but there is nowhere to show a card —
 *   the pill replaces the whole arcade.
 */
export type PauseTrigger = "agent-stop" | "minimized";

export interface PauseState {
  readonly paused: boolean;
  readonly trigger: PauseTrigger | null;
}

/** The shift is free to advance. */
export const RUNNING: PauseState = { paused: false, trigger: null };

export function pausedFor(trigger: PauseTrigger): PauseState {
  return { paused: true, trigger };
}

export interface AgentPauseInput {
  /** A run is on screen — not the menu, the gate, or a finished shift. */
  readonly inGame: boolean;
  /** The player's "Auto-pause when agent stops" preference. */
  readonly autoPauseOnStop: boolean;
  /** Already stopped, for some other reason. */
  readonly alreadyPaused: boolean;
}

/**
 * Whether a host `gamepigeon:pause` should actually interrupt the player.
 *
 * Note this decides only the *interruption*. Rust shows and focuses the window
 * on its own before dispatching, which is what makes the preference matter:
 * with auto-pause off the window still comes forward, it just doesn't take the
 * shift away from whoever is mid-service.
 */
export function shouldPauseForAgent(input: AgentPauseInput): boolean {
  if (!input.autoPauseOnStop) return false;
  if (!input.inGame) return false;
  return !input.alreadyPaused;
}

/** True when this pause has a card to show; `minimized` has nowhere to put one. */
export function showsPausePrompt(state: PauseState): boolean {
  return state.paused && state.trigger === "agent-stop";
}

/**
 * The paused card's heading. It names the thing that stopped the shift,
 * because that is also the thing the player has to decide about: the agent is
 * waiting on them, or it isn't.
 */
export function pausePromptTitle(state: PauseState): string {
  return state.trigger === "agent-stop" ? "Your agent needs you" : "Paused";
}

