/**
 * When the overlay stops a shift by itself, and what it says while stopped.
 *
 * Split out of app.ts because the interesting part is a decision rather than a
 * repaint. The host's `Stop` hook fires `gamepigeon:pause` at every turn
 * boundary — with or without a run on screen, with or without the player
 * having asked for that behaviour — so "did the agent stop" and "should the
 * player be interrupted" are two different questions.
 *
 * Nothing in here touches the DOM or the engine: pausing is a state, and the
 * two things that read it (the timer that advances the shift, and the paused
 * card) both derive from that state.
 */

/**
 * Why the shift is stopped.
 *
 * - `agent-stop`: the harness reported the agent needs the player. This is the
 *   only trigger that puts a card on screen.
 * - `minimized`: the floor was collapsed to the pill. A shift the player
 *   cannot see must not keep running, but there is nowhere to show a card —
 *   the pill replaces the whole arcade.
 */
export type PauseTrigger = "agent-stop" | "minimized";

export interface PauseState {
  readonly paused: boolean;
  readonly trigger: PauseTrigger | null;
}

/** The shift is free to advance. */
export const RUNNING: PauseState = { paused: false, trigger: null };

export function pausedFor(trigger: PauseTrigger): PauseState {
  return { paused: true, trigger };
}

export interface AgentPauseInput {
  /** A run is on screen — not the menu, the gate, or a finished shift. */
  readonly inGame: boolean;
  /** The player's "Auto-pause when agent stops" preference. */
  readonly autoPauseOnStop: boolean;
  /** Already stopped, for some other reason. */
  readonly alreadyPaused: boolean;
}

/**
 * Whether a host `gamepigeon:pause` should actually interrupt the player.
 *
 * Note this decides only the *interruption*. Rust shows and focuses the window
 * on its own before dispatching, which is what makes the preference matter:
 * with auto-pause off the window still comes forward, it just doesn't take the
 * shift away from whoever is mid-service.
 */
export function shouldPauseForAgent(input: AgentPauseInput): boolean {
  if (!input.autoPauseOnStop) return false;
  if (!input.inGame) return false;
  return !input.alreadyPaused;
}

/** True when this pause has a card to show; `minimized` has nowhere to put one. */
export function showsPausePrompt(state: PauseState): boolean {
  return state.paused && state.trigger === "agent-stop";
}

/**
 * The paused card's heading. It names the thing that stopped the shift,
 * because that is also the thing the player has to decide about: the agent is
 * waiting on them, or it isn't.
 */
export function pausePromptTitle(state: PauseState): string {
  return state.trigger === "agent-stop" ? "Your agent needs you" : "Paused";
}

import type { GameEntry, PlayableGame } from "../src/games/registry.js";

const STORAGE_KEY = "gamepigeon.arcade.active-game.v1";
const MAX_ACTIONS = 50_000;

export interface SavedGame {
  schemaVersion: 1;
  ownerId: string;
  gameId: string;
  gameVersion: string;
  variationId: string;
  seed: number;
  actions: string[];
}

export interface RestoredGame {
  game: PlayableGame;
  actions: string[];
}

function validSavedGame(value: unknown): value is SavedGame {
  if (!value || typeof value !== "object") return false;
  const saved = value as Partial<SavedGame>;
  return saved.schemaVersion === 1
    && typeof saved.ownerId === "string"
    && typeof saved.gameId === "string"
    && typeof saved.gameVersion === "string"
    && typeof saved.variationId === "string"
    && Number.isInteger(saved.seed)
    && Array.isArray(saved.actions)
    && saved.actions.length <= MAX_ACTIONS
    && saved.actions.every((action) => typeof action === "string");
}

export function loadSavedGame(storage: Storage = localStorage): SavedGame | null {
  try {
    const raw = storage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const saved: unknown = JSON.parse(raw);
    return validSavedGame(saved) ? saved : null;
  } catch {
    return null;
  }
}

/**
 * Writes the one active-game record, replacing whatever was there.
 *
 * A run longer than {@link MAX_ACTIONS} stops extending the record rather than
 * replacing it with something `loadSavedGame` would reject: what is already
 * stored is a valid prefix of this same seeded run, so the next launch still
 * resumes — just a little earlier than the player left off.
 */
export function saveGame(saved: SavedGame, storage: Storage = localStorage): void {
  if (saved.actions.length > MAX_ACTIONS) return;
  try {
    storage.setItem(STORAGE_KEY, JSON.stringify(saved));
  } catch {
    // A full or blocked store must never interrupt the run it is describing.
  }
}

/** Drops the record entirely — a restart replaces the run, it doesn't continue it. */
export function clearSavedGame(storage: Storage = localStorage): void {
  try {
    storage.removeItem(STORAGE_KEY);
  } catch {
    // Same: losing the save is survivable, throwing mid-run is not.
  }
}

/** Rebuild only actions that remain accepted by this version of the game. */
export function restoreGame(entry: GameEntry, saved: SavedGame): RestoredGame | null {
  if (!entry.create || saved.gameId !== entry.id || saved.gameVersion !== entry.version) return null;
  const game = entry.create(saved.variationId);
  game.reset(saved.seed);
  const actions: string[] = [];
  for (const action of saved.actions) {
    if (!(game.actions as readonly string[]).includes(action)) return null;
    if (game.step(action).moved) actions.push(action);
  }
  return { game, actions };
}

/**
 * Thin Tauri façade so the overlay boots in a plain browser (preview mode).
 * Production Tauri packaging is unchanged — real APIs are used when present.
 */

import { invoke as tauriInvoke } from "@tauri-apps/api/core";
import { getCurrentWindow, LogicalSize as TauriLogicalSize } from "@tauri-apps/api/window";

export const PREVIEW_RESIZE_MESSAGE = "gamepigeon:preview-resize";

type TauriWindow = ReturnType<typeof getCurrentWindow>;

export type OverlayWindow = Pick<
  TauriWindow,
  "hide" | "setSize" | "setMinSize" | "center" | "startDragging"
>;

export function isTauri(): boolean {
  if (typeof window === "undefined") return false;
  const w = window as Window & { __TAURI_INTERNALS__?: unknown; __TAURI__?: unknown };
  return Boolean(w.__TAURI_INTERNALS__ || w.__TAURI__);
}

/** A logical (DPI-independent) frame size, in the units Tauri calls logical. */
export interface OverlaySize {
  readonly width: number;
  readonly height: number;
}

/**
 * The four frames the overlay ever takes. The browser preview mirrors these
 * pixel for pixel, and README's "Window sizes" table is these values — keep
 * the three in step.
 */
export const COMPACT_SIZE: OverlaySize = { width: 600, height: 850 };
export const EXPANDED_SIZE: OverlaySize = { width: 830, height: 900 };
export const PILL_SIZE: OverlaySize = { width: 144, height: 48 };
/** The floor's minimum. The pill is deliberately below it; nothing else is. */
export const MIN_SIZE: OverlaySize = { width: 500, height: 700 };

export type WindowSizeMode = "compact" | "expanded";

/** The frame the floor takes for a size preference, never below {@link MIN_SIZE}. */
export function floorSize(mode: WindowSizeMode): OverlaySize {
  const target = mode === "expanded" ? EXPANDED_SIZE : COMPACT_SIZE;
  return {
    width: Math.max(target.width, MIN_SIZE.width),
    height: Math.max(target.height, MIN_SIZE.height),
  };
}

export class LogicalSize {
  readonly width: number;
  readonly height: number;

  constructor(width: number, height: number) {
    this.width = width;
    this.height = height;
  }
}

function sizeParts(size: LogicalSize | TauriLogicalSize | { width: number; height: number }): {
  width: number;
  height: number;
} {
  return { width: size.width, height: size.height };
}

function notifyPreviewResize(width: number, height: number): void {
  const detail = { type: PREVIEW_RESIZE_MESSAGE, width, height };
  window.parent?.postMessage(detail, window.location.origin);
  window.dispatchEvent(new CustomEvent(PREVIEW_RESIZE_MESSAGE, { detail }));
}

function browserWindow(): OverlayWindow {
  return {
    hide: async () => {
      console.info("[preview] hide");
    },
    setSize: async (size) => {
      const { width, height } = sizeParts(size as LogicalSize);
      notifyPreviewResize(width, height);
    },
    setMinSize: async () => {
      /* the preview iframe has no min size to enforce */
    },
    center: async () => {
      /* no-op in browser preview */
    },
    startDragging: async () => {
      /* no-op in browser preview */
    },
  };
}

let cachedWindow: OverlayWindow | undefined;

export function getOverlayWindow(): OverlayWindow {
  if (!cachedWindow) {
    cachedWindow = isTauri() ? getCurrentWindow() : browserWindow();
  }
  return cachedWindow;
}

async function previewInvoke<T>(cmd: string, args?: Record<string, unknown>): Promise<T> {
  const path = cmd === "read_worker_model_config"
    ? "/api/worker-model/config"
    : cmd === "complete_worker_model"
      ? "/api/worker-model/complete"
      : cmd === "cancel_worker_model"
        ? "/api/worker-model/cancel"
        : undefined;
  if (!path) {
    console.info(`[preview] invoke(${cmd})`, args ?? {});
    return undefined as T;
  }
  const response = await fetch(path, {
    method: cmd === "read_worker_model_config" ? "GET" : "POST",
    headers: cmd === "read_worker_model_config" ? undefined : { "Content-Type": "application/json" },
    body: cmd === "read_worker_model_config" ? undefined : JSON.stringify(args ?? {}),
  });
  if (response.status === 204) return undefined as T;
  if (!response.ok) throw new Error(await response.text());
  return response.json() as Promise<T>;
}

export async function invoke<T>(cmd: string, args?: Record<string, unknown>): Promise<T> {
  if (isTauri()) return tauriInvoke<T>(cmd, args);
  return previewInvoke<T>(cmd, args);
}

/** Prefer the real Tauri LogicalSize under Tauri so setSize accepts it. */
export function overlayLogicalSize(width: number, height: number): LogicalSize | TauriLogicalSize {
  return isTauri() ? new TauriLogicalSize(width, height) : new LogicalSize(width, height);
}

/**
 * The browser stand-in is structural, and the preview's `setSize` only ever
 * reads `width`/`height` off it — so the one place that difference exists is
 * here, rather than at every call site.
 */
function windowSize(size: OverlaySize): TauriLogicalSize {
  return overlayLogicalSize(size.width, size.height) as TauriLogicalSize;
}

/**
 * Resizes the overlay frame. The minimum is written first, always: collapsing
 * to the pill goes *below* the floor minimum, so a minimum still set to the
 * floor's would clamp the pill straight back up to 500 × 700.
 */
export async function applyOverlaySize(size: OverlaySize, minSize: OverlaySize = size): Promise<void> {
  const handle = getOverlayWindow();
  await handle.setMinSize(windowSize(minSize));
  await handle.setSize(windowSize(size));
}

