576	interface WorkerModelResponse {
577	  text: string;
578	  queueMs: number;
579	  providerMs: number;
580	  inputTokens?: number;
581	  outputTokens?: number;
582	  cachedInputTokens?: number;
583	  finishReason?: string;
584	}
585	
586	/** Absent provider fields (no usage on this response) stay absent, not zero. */
587	function workerModelMetrics(response: WorkerModelResponse): ModelCallMetrics {
588	  return {
589	    queueMs: response.queueMs,
590	    providerMs: response.providerMs,
591	    ...(response.inputTokens !== undefined ? { inputTokens: response.inputTokens } : {}),
592	    ...(response.outputTokens !== undefined ? { outputTokens: response.outputTokens } : {}),
593	    ...(response.cachedInputTokens !== undefined ? { cachedInputTokens: response.cachedInputTokens } : {}),
594	    ...(response.finishReason !== undefined ? { finishReason: response.finishReason } : {}),
595	  };
596	}
597	
598	function attachWorkerOrchestrator(activeGame: PlayableGame): void {
599	  if (!workerModel || activeGame.name !== "restaurant-arena") return;
600	  workerActivity.length = 0;
601	  const arena = activeGame as unknown as RestaurantGame;
602	  const client = new WorkerModelClient({
603	    retries: 0,
604	    // The Rust transport bounds the provider call and starts that bound after
605	    // the request budget admits it, so queue time is not charged to the
606	    // worker. A timer here would start while the request is still in line and
607	    // abort a crew that is only waiting its turn.
608	    timeoutMs: null,
609	    complete: async (request: ModelRequest, signal: AbortSignal) => {
610	      const role = request.observation.role;
611	      const startedAt = performance.now();
612	      setWorkerStatus(role, "thinking");
613	      // A request already queued behind the account's share is not pending on
614	      // the model; the budget banner is the more specific thing to say. The
615	      // activity feed still logs the request either way -- it is a log of what
616	      // happened, not a description of the current state.
617	      if (shouldReportFallback(workerBudget)) setWorkerMode(`Pending · ${workerModelLabel()} · ${role}`, "pending");
618	      addWorkerActivity(`${role}: requested live action`);
619	      const requestId = crypto.randomUUID();
620	      const cancel = () => void invoke("cancel_worker_model", { requestId });
621	      signal.addEventListener("abort", cancel, { once: true });
622	      try {
623	        const response = await invoke<WorkerModelResponse>("complete_worker_model", {
624	          requestId,
625	          request: { systemPrompt: request.systemPrompt, turnPrompt: request.turnPrompt },
626	        });
627	        if (signal.aborted) throw new Error("model request canceled");
628	        setWorkerStatus(role, "acting");
629	        addWorkerActivity(`${role}: response received in ${Math.round(performance.now() - startedAt)}ms`);
630	        return { text: response.text, metrics: workerModelMetrics(response) };
631	      } finally {
632	        signal.removeEventListener("abort", cancel);
633	      }
634	    },
635	  });
636	  let orchestrator: WorkerOrchestrator;
637	  orchestrator = new WorkerOrchestrator(arena, {
638	    client,
639	    model: workerModel,
640	    tickIntervalMs: () => arena.tickMs() || 1_000,
641	    onError: (turn) => {
642	      if (workerOrchestrator !== orchestrator) return;
643	      setWorkerStatus(turn.role, "error");
644	      addWorkerActivity(`${turn.role}: fallback — ${turn.error ?? "invalid action"}`);
645	      // A shift held back by the shared account is waiting, not broken (#281).
646	      // Only the banner is suppressed; the feed above still records the turn.
647	      if (!shouldReportFallback(workerBudget)) return;
648	      setWorkerMode(`Fallback · ${workerModelLabel()} · ${turn.role}: ${turn.error ?? "invalid action"}`, "error");
649	    },
650	    onTick: (report: OrchestratorTick) => {
651	      if (workerOrchestrator !== orchestrator || game !== activeGame) return;
652	      for (const turn of report.turns) {
653	        if (turn.status === "accepted") {
654	          setWorkerStatus(turn.role, "acting");
655	          addWorkerActivity(`${turn.role}: applied ${turn.action?.tool ?? "action"}`);
656	        }
657	        else if (turn.status === "fallback" || turn.status === "rejected") setWorkerStatus(turn.role, "error");
658	      }
659	      // Turns landing again is proof the account is answering, whatever the
660	      // last throttle said was left on its countdown.
661	      if (report.turns.every((turn) => turn.status === "accepted")) setWorkerBudget(WORKER_BUDGET_CLEAR);
662	      drawGame();
663	    },
664	  });
665	  workerOrchestrator = orchestrator;
666	}
