668	/** Every control funnels through here — the panel's only write path. */
669	function submitIntervention(input: PlayerInterventionInput): void {
670	  if (!game) return;
671	  const withIntervene = game as PlayableGame & {
672	    submitPlayerIntervention?: (i: PlayerInterventionInput) => { accepted: boolean; error?: { message: string } };
673	  };
674	  if (!withIntervene.submitPlayerIntervention) return;
675	  workerOrchestrator?.pause();
676	  const result = withIntervene.submitPlayerIntervention(input);
677	  if (result.accepted) {
678	    setInterveneStatus("Sent.");
679	  } else {
680	    setInterveneStatus(result.error?.message ?? "Could not send that.", "error");
681	  }
682	  // A rejected stale/invalid intervention must not strand live workers in the
683	  // paused state either; drawGame() re-enters the selected scheduler.
684	  drawGame();
685	}
