687	/** Wire the static shell once per mount; content refreshes in place after. */
688	function bindInterventionPanel(): void {
689	  const els = interveneEls();
690	  if (!els.toggle || !els.panel) return;
691	  interveneRole = "chef";
692	
693	  els.toggle.addEventListener("click", () => {
694	    const opening = els.panel!.hidden;
695	    els.panel!.hidden = !opening;
696	    els.toggle!.setAttribute("aria-expanded", String(opening));
697	    if (opening && game) refreshInterventionPanel(game);
698	  });
699	  els.close?.addEventListener("click", () => {
700	    els.panel!.hidden = true;
701	    els.toggle!.setAttribute("aria-expanded", "false");
702	  });
703	  els.roles?.addEventListener("click", (event) => {
704	    const target = (event.target as HTMLElement).closest<HTMLButtonElement>("[data-role]");
705	    if (!target?.dataset.role) return;
706	    interveneRole = target.dataset.role as PlayerInterventionInput["targetRole"];
707	    els.roles!.querySelectorAll<HTMLButtonElement>("[data-role]").forEach((btn) => btn.classList.toggle("is-selected", btn === target));
708	  });
709	  els.send?.addEventListener("click", () => {
710	    const text = els.text?.value.trim() ?? "";
711	    if (!text) {
712	      setInterveneStatus("Say something first.", "error");
713	      return;
714	    }
715	    submitIntervention({ kind: "message", targetRole: interveneRole, text, priority: els.urgent?.checked ? "high" : "normal" });
716	    if (els.text) els.text.value = "";
717	    if (els.urgent) els.urgent.checked = false;
718	  });
719	  els.correct?.addEventListener("click", () => {
720	    submitIntervention({ kind: "correction", targetRole: interveneRole });
721	  });
722	  // Passing is a decision, so it goes on the record like any other. Doing
723	  // nothing and choosing to do nothing read identically in a trace otherwise.
