929	/**
930	 * The evidence receipt: what the shift actually recorded, counted off the
931	 * run's own journal — the same events `Export Trace` writes out as
932	 * restaurant-arena-trace/v3.
933	 *
934	 * Split by who authored each event, because that split is the whole point of
935	 * the export: what the house did on its own (`system`) has to stay separable
936	 * from what the manager handed over (`player`) and what the workers did with
937	 * it. Every number here is counted, never estimated, and nothing is
938	 * attributed to a model that did not stamp the event itself.
939	 */
940	function getArenaEvidenceHtml(): string {
941	  if (!game || game.name !== "restaurant-arena") return "";
942	  const journal = game as unknown as { getRecordedEvents?: () => { actorId?: string; model?: unknown; toolResult?: { ok?: boolean } | null }[] };
943	  if (typeof journal.getRecordedEvents !== "function") return "";
944	  let events: { actorId?: string; model?: unknown; toolResult?: { ok?: boolean } | null }[];
945	  try {
946	    events = journal.getRecordedEvents();
947	  } catch (err) {
948	    console.error("Failed to read the arena event journal:", err);
949	    return "";
950	  }
951	  const system = events.filter((event) => event.actorId === "system").length;
952	  const manager = events.filter((event) => event.actorId === "player").length;
953	  const worker = events.length - system - manager;
954	  const rejected = events.filter((event) => event.toolResult?.ok === false).length;
955	  const modelStamped = events.filter((event) => event.model !== undefined && event.model !== null).length;
956	  // Only the authorship split gets tiles — that split is what the export is
957	  // for. The rest is one line, because a six-tile grid made a footnote look
958	  // like a scoreboard.
959	  const rows: [string, string][] = [
960	    ["System", `${system}`],
961	    ["Your handover", `${manager}`],
962	    ["Worker turns", `${worker}`],
963	  ];
964	  return `
965	    <div class="arena-evidence">
966	      <p class="debrief-criteria">${events.length} recorded events · exported by <code>Export Trace</code></p>
967	      <div class="evidence-stats">${rows
968	        .map(([label, value]) => `<span class="evidence-stat"><small>${escapeHtml(label)}</small><strong>${escapeHtml(value)}</strong></span>`)
969	        .join("")}</div>
970	      <p class="debrief-caveat">${rejected} rejected call${rejected === 1 ? "" : "s"} · ${modelStamped} stamped by a model. Counted from this run&rsquo;s journal, never inferred.</p>
971	    </div>`;
972	}
