.game-end-overlay {
  position: absolute;
  inset: 0;
  z-index: 5;
  display: grid;
  place-items: center;
  padding: 16px;
  background: rgba(6, 10, 14, 0.82);
  backdrop-filter: blur(4px);
  border-radius: inherit;
  animation: fade-in 0.25s ease-out;
}
@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
.game-end-content {
  width: 100%;
  max-width: 300px;
  text-align: center;
}
.game-end-title {
  margin: 0 0 10px;
  font-size: 24px;
  font-weight: 800;
  letter-spacing: -.02em;
  color: #f8fafc;
  text-shadow: 0 1px 3px rgba(0, 0, 0, .4);
}
.game-end-overlay[data-tone="win"] .game-end-title { color: var(--gold); }
.game-end-overlay[data-tone="loss"] .game-end-title { color: var(--danger); }
.game-end-overlay[data-tone="draw"] .game-end-title { color: var(--blue); }

.game-end-stats {
  margin: 0 auto 20px;
  max-width: 240px;
  padding-top: 12px;
  border-top: 1px solid rgba(255, 255, 255, .14);
  font-size: 13.5px;
  font-weight: 500;
  color: rgba(255, 255, 255, .78);
  line-height: 1.55;
  letter-spacing: .01em;
}
/* Service report on the end-of-shift card: the local grade, the six
   numbers it was built from, and what to do differently next run. */
.arena-debrief { margin: 0 auto 18px; max-width: 300px; text-align: left; }
.debrief-scope, .debrief-criteria {
  margin: 0 0 6px;
  text-align: center;
  font: 700 8px/1.35 var(--mono);
  color: rgba(255, 255, 255, .5);
}
.debrief-scope { text-transform: uppercase; letter-spacing: .08em; }
.debrief-criteria { margin-bottom: 8px; }
.debrief-target {
  margin: 0 0 6px;
  text-align: center;
  font: 800 9px/1.3 var(--mono);
  letter-spacing: .14em;
  color: #f08a7a;
}
.arena-debrief[data-met="yes"] .debrief-target { color: #7ddc9f; }
.debrief-grade { margin: 0 0 10px; text-align: center; font-size: 13px; color: rgba(255, 255, 255, .8); }
.debrief-grade strong {
  display: inline-block;
  min-width: 26px;
  margin-right: 8px;
  padding: 1px 7px;
  border-radius: 6px;
  background: #f2cc5c;
  color: #2b2118;
  font: 800 15px/1.3 var(--mono);
}
/* Two across, not three: the target checks now absorb two of the six
   stats, and four tiles in a three-column grid left an orphan. */
.debrief-stats { display: grid; grid-template-columns: repeat(2, 1fr); gap: 6px 8px; margin-bottom: 12px; }
.debrief-stat { display: grid; gap: 1px; padding: 5px 6px; border-radius: 7px; background: rgba(255, 255, 255, .07); }
.debrief-stat small { font: 700 8px/1.2 var(--mono); letter-spacing: .06em; text-transform: uppercase; color: rgba(255, 255, 255, .5); }
.debrief-stat strong { font: 800 12px/1.2 var(--mono); color: #f08a7a; }
.debrief-stat.is-good strong { color: #7ddc9f; }
/* The conditions the verdict was actually computed from. Kept visually
   distinct from `.debrief-stats`, which grade the shift on softer
   read-at-a-glance thresholds rather than tonight's pass bar. */
.debrief-checks { margin: 0 0 12px; padding: 0; list-style: none; display: grid; gap: 4px; }
.debrief-check {
  display: grid;
  grid-template-columns: 14px 1fr auto auto;
  align-items: baseline;
  gap: 6px;
  padding: 4px 7px;
  border-radius: 7px;
  background: rgba(240, 138, 122, .12);
  font: 700 10px/1.3 var(--mono);
  color: rgba(255, 255, 255, .82);
}
.debrief-check.is-met { background: rgba(125, 220, 159, .12); }
.debrief-check .check-mark { color: #f08a7a; font-weight: 800; }
.debrief-check.is-met .check-mark { color: #7ddc9f; }
.debrief-check .check-label { font-weight: 600; }
.debrief-check .check-value { font-weight: 800; }
.debrief-check .check-req { font-weight: 600; color: rgba(255, 255, 255, .45); }
.debrief-caveat {
  margin: 0 0 12px;
  font: 400 9.5px/1.45 var(--mono);
  color: rgba(255, 255, 255, .45);
}
/* What the run recorded, counted off its own journal — the receipt for
   the trace the export buttons below write out. */
.arena-evidence { margin: 0 auto 18px; max-width: 300px; text-align: left; }
.arena-evidence code { font: 700 9px/1.3 var(--mono); color: rgba(255, 255, 255, .7); }
.evidence-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin-bottom: 6px; }
.evidence-stat { display: grid; gap: 1px; padding: 5px 6px; border-radius: 7px; background: rgba(255, 255, 255, .05); }
.evidence-stat small { font: 700 7.5px/1.2 var(--mono); letter-spacing: .05em; text-transform: uppercase; color: rgba(255, 255, 255, .45); }
.evidence-stat strong { font: 800 12px/1.2 var(--mono); color: rgba(255, 255, 255, .85); }
.debrief-lessons { margin: 0; padding-left: 16px; display: grid; gap: 5px; }
.debrief-lessons li { font-size: 11.5px; line-height: 1.45; color: rgba(255, 255, 255, .7); }
.game-end-actions {
  display: grid;
  gap: 10px;
  margin-top: 4px;
}
.game-end-actions button {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 40px;
  padding: 0 14px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-s);
  background: var(--bg-2);
  color: var(--ink);
  cursor: pointer;
  font-size: 13px;
  font-weight: 600;
  text-align: center;
  transition: border-color .12s ease, background .12s ease;
}
.game-end-actions button:hover, .game-end-actions button:focus-visible {
  border-color: var(--hover);
  background: var(--bg-3);
  outline: none;
}
.game-end-actions .primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-ink);
  font-weight: 700;
}
.game-end-actions .primary:hover, .game-end-actions .primary:focus-visible {
  background: var(--banana-deep);
}

/* Arena expanded end-card with timeline and trace export */
.game-end-content.arena-end-content {
  max-width: min(92vw, 420px);
  max-height: 92vh;
  overflow-y: auto;
  padding: 4px 6px 12px;
  box-sizing: border-box;
}
.game-end-content.arena-end-content::-webkit-scrollbar {
  width: 4px;
}
.game-end-content.arena-end-content::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border-radius: 4px;
}
.arena-timeline {
  margin: 12px 0 16px;
  text-align: left;
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(255, 255, 255, 0.12);

