/** Which staff member the intervention panel currently addresses. */
let interveneRole: PlayerInterventionTarget = "chef";

// ── Session lifecycle state ───────────────────────────────────────────
//
// A "run" is one seeded shift: the game instance, the seed it was reset with,
// the variation it was launched from, and the ordered actions that moved it.
// Those four are exactly the `SavedGame` record, which is why they live
// together here rather than being re-derived from the engine at save time.

/** Whether the shift is advancing, and what stopped it if it isn't. */
let pauseState: PauseState = CLOCK_RUNNING;
/** The floor, or the 144 × 48 pill that replaces it. */
let windowMode: "floor" | "pill" = "floor";
/** The deterministic auto-advance timer; a live crew keeps its own. */
let tickTimer: number | undefined;
/** The seed the run on screen was reset with — never re-randomized mid-run. */
let runSeed = 0;
let runVariationId = "";
/** Only actions the engine accepted, in order: the replayable journal. */
let runActions: string[] = [];
/** A launch that arrived before boot finished, replayed once it has. */
let pendingLaunch: { gameId: string; variationId?: string } | undefined;

