function saveSetting(key: string, value: unknown): void {
  if (!(key in settings)) return;
  (settings as unknown as Record<string, unknown>)[key] = value;
  localStorage.setItem("gamepigeon.settings.productAnalytics", String(settings.productAnalytics));
  void invoke("write_settings", { settings: { [key]: value } }).catch(() => undefined);
  // Picking a frame size in Settings shows you the frame, rather than saving a
  // preference that only takes effect on some future launch.
  if (key === "defaultWindowSize") {
    expanded = settings.defaultWindowSize === "expanded";
    renderResizeButton();
    applyWindowSize();
  }
  if (screen === "settings") drawSettings();
}

// ── Window chrome ─────────────────────────────────────────────────────
//
// Three frames and one rule: the pill is the only state allowed below the
// floor's 500 × 700 minimum, and restoring from it always comes back compact
// (README, "Window sizes"). `tauri-bridge.ts` owns the numbers; this owns
// which one is current and what the titlebar says about it.

/** Pushes the current frame to the window, and optionally recentres it. */
function applyWindowSize(center = false): void {
  const pill = windowMode === "pill";
  const target = pill ? PILL_SIZE : floorSize(expanded ? "expanded" : "compact");
  void applyOverlaySize(target, pill ? PILL_SIZE : MIN_SIZE)
    .then(() => (center ? windowHandle.center() : undefined))
    .catch(() => {
      // A frame the window manager refuses is not worth interrupting a shift.
    });
}

/** The titlebar control names the frame it would move you *to*, not the one you are in. */
function renderResizeButton(): void {
  const button = document.querySelector<HTMLButtonElement>("#resize");
  if (!button) return;
  button.textContent = expanded ? "↙" : "↗";
  button.setAttribute("aria-label", expanded ? "Compact overlay" : "Expand overlay");
}

function toggleWindowSize(): void {
  // Collapsed, there is no compact/expanded distinction to toggle — the only
  // larger frame is the floor itself.
  if (windowMode === "pill") {
    restoreFromPill();
    return;
  }
  expanded = !expanded;
  renderResizeButton();
  applyWindowSize();
}

function minimizeToPill(): void {
  // A shift nobody can see must not keep serving tables. `pauseRun` leaves an
  // existing pause alone, so collapsing an agent-stop pause keeps its card.
  pauseRun("minimized");
  windowMode = "pill";
  document.body.dataset.mode = "pill";
  applyWindowSize();
  document.querySelector<HTMLButtonElement>("#pill")?.focus();
}

function restoreFromPill(): void {
  if (windowMode !== "pill") return;
  windowMode = "floor";
  delete document.body.dataset.mode;
  // Always compact, whatever the frame was before collapsing (README).
  expanded = false;
  renderResizeButton();
  applyWindowSize();
  // Only the collapse itself is undone here: a shift the agent stopped is
  // still stopped, and its card comes back with the floor.
  if (pauseState.trigger === "minimized") resumeRun();
  else scheduleClock();
}

/** Ends the session for good. Whatever the run had is written down first. */
async function shutdownOverlay(): Promise<void> {
  parkRunForRecovery();
  await invoke("shutdown").catch(() => undefined);
}

/**
 * Hands over everything the next launch would need: the run's own journal, and
 * any recording chunks that are already sealed. The episode is deliberately
 * *not* ended — `recoverTraces()` closes it as `client_closed` next time,
 * which is the honest reason.
 */
function parkRunForRecovery(): void {
  persistRun();
  if (activeTrace) flushSealedTrace(activeTrace);
}

/**
 * Dragging the pill has to be told apart from clicking it, and Tauri's
 * `startDragging` swallows every later pointer event — so movement past a
 * small threshold both starts the drag and marks the gesture, and the click
 * that may still arrive afterwards is spent on clearing that mark.
 */
const PILL_DRAG_THRESHOLD_PX = 4;

function bindPill(): void {
  const pill = document.querySelector<HTMLButtonElement>("#pill");
  if (!pill) return;
  let origin: { x: number; y: number } | null = null;
  let dragged = false;
  pill.addEventListener("pointerdown", (event) => {
    if (event.button !== 0) return;
    origin = { x: event.clientX, y: event.clientY };
    dragged = false;
  });
  pill.addEventListener("pointermove", (event) => {
    if (!origin) return;
    if (
      Math.abs(event.clientX - origin.x) < PILL_DRAG_THRESHOLD_PX
      && Math.abs(event.clientY - origin.y) < PILL_DRAG_THRESHOLD_PX
    ) return;
    origin = null;
    dragged = true;
    void windowHandle.startDragging().catch(() => undefined);
  });
  pill.addEventListener("pointerup", () => { origin = null; });
  pill.addEventListener("click", () => {
    if (dragged) {
      dragged = false;
      return;
    }
    restoreFromPill();
  });
}

// ── Modal cards ───────────────────────────────────────────────────────
//
// All three live in index.html rather than being rendered, because all three
// outlive the screen underneath them. Exactly one can be open, and while one
// is open the shift's clock is held (see `scheduleClock`) — a guide or a
// confirmation over the board must not cost the player tables.

type Dialog = "pause" | "how-to-play" | "signout";

const DIALOGS: Readonly<Record<Dialog, string>> = {
  pause: "#return-prompt",
  "how-to-play": "#how-to-play",
  signout: "#signout-prompt",
};

let dialog: Dialog | null = null;
/** True when How to Play was opened *from* the paused card, so Got it goes back. */
let howToPlayReturnsToPause = false;

function setDialog(next: Dialog | null): void {
  dialog = next;
  for (const name of Object.keys(DIALOGS) as Dialog[]) {
    const el = document.querySelector<HTMLElement>(DIALOGS[name]);
    if (el) el.hidden = name !== next;
  }
  if (next === "pause") {
    const title = document.querySelector<HTMLElement>("#return-title");
    if (title) title.textContent = pausePromptTitle(pauseState);
  }
  if (next === "signout") setSignOutError(null);
  // Focusing the card's primary is what makes `Enter` work without this
  // module handling it: the browser activates the focused button, and the
  // primary is always the action the card's own label promises for Enter.
  if (next) document.querySelector<HTMLButtonElement>(`${DIALOGS[next]} .primary`)?.focus();
}

function closeDialog(): void {
  setDialog(null);
  scheduleClock();
}

function openHowToPlay(fromPause = false): void {
  howToPlayReturnsToPause = fromPause;
  setDialog("how-to-play");
  scheduleClock();
}

function closeHowToPlay(): void {
  if (howToPlayReturnsToPause) {
    howToPlayReturnsToPause = false;
    setDialog("pause");
    scheduleClock();
    return;
  }
  closeDialog();
}

function setSignOutError(message: string | null): void {
  const el = document.querySelector<HTMLElement>("#signout-error");
  if (!el) return;
  el.hidden = message === null;
  el.textContent = message ?? "";
}

function openSignOutPrompt(): void {
  setDialog("signout");
  scheduleClock();
}

/**
 * `signOut()` throws with the stored session still on disk, so a failure has
 * to leave the player signed in and say why — reporting a sign-out that did
 * not happen is the one outcome worth guarding against here.
 */
async function confirmSignOut(): Promise<void> {
  const confirmButton = document.querySelector<HTMLButtonElement>("#signout-confirm");
  if (confirmButton) confirmButton.disabled = true;
  setSignOutError(null);
  try {
    await signOut();
  } catch (error) {
    setSignOutError(error instanceof Error ? error.message : String(error));
    return;
  } finally {
    if (confirmButton) confirmButton.disabled = false;
  }
  // The shift belonged to the account that just left. The `SavedGame` record
  // is owner-scoped, so it stays on disk — signing back in resumes it — but
  // nothing signed-in stays on screen.
  endGame("user_quit");
  teardownRun();
  game = undefined;
  entry = undefined;
  gameEnded = false;
  savedGame = undefined;
  localScores = { personal_bests: [], recent: [], top_scores: [] };
  clearSignInPending();
  setDialog(null);
  drawGate();
}

/** The action the card's `.primary` performs, for when focus has left the card. */
function activateDialogPrimary(): void {
  if (dialog === "signout") void confirmSignOut();
  else if (dialog === "how-to-play") closeHowToPlay();
  else if (dialog === "pause") backToCoding();
}

function dialogHasFocus(): boolean {
  if (!dialog) return false;
  const card = document.querySelector<HTMLElement>(DIALOGS[dialog]);
  const active = document.activeElement;
  return Boolean(card && active instanceof Node && card.contains(active));
}

function handleDialogKey(event: KeyboardEvent): void {
  if (!dialog) return;
  if (event.key === "Escape") {
    event.preventDefault();
    if (dialog === "signout") closeDialog();
    else if (dialog === "how-to-play") closeHowToPlay();
    else backToCoding();
    return;
  }
  if (event.key === "Enter") {
    // Normally the focused primary handles this; only a click that moved
    // focus off the card leaves it to us.
    if (dialogHasFocus()) return;
    event.preventDefault();
    activateDialogPrimary();
    return;
  }
  if (dialog === "pause" && event.key.toLowerCase() === "m") {
    event.preventDefault();
    leaveToMenu();
  }
}

// ── Pausing ───────────────────────────────────────────────────────────

/** Stops the shift, and puts a card up if this pause has one to show. */
function pauseRun(trigger: PauseTrigger): void {
  if (screen !== "game" || !game || gameEnded) return;
  // The first reason wins: it is the one the player has to answer.
  if (pauseState.paused) return;
  pauseState = pausedFor(trigger);
  if (showsPausePrompt(pauseState)) setDialog("pause");
  scheduleClock();
}

function resumeRun(): void {
  if (dialog === "pause") setDialog(null);
  if (!pauseState.paused) {
    scheduleClock();
    return;
  }
  pauseState = CLOCK_RUNNING;
  scheduleClock();
}

/**
 * The paused card's primary, and what the `Stop` hook's `Enter` shortcut does:
 * get out of the way without giving up the shift. The run stays paused exactly
 * as it was, so the card is still there when the floor comes back.
 */
function backToCoding(): void {
  minimizeToPill();
}

