input.new_string:
/**
 * The one repaint every path goes through, which is also why the shift is
 * settled here: whether a step came from a key, a click, the tick timer or a
 * live worker's turn, it ends up drawing — so `endGame` is reached exactly
 * once, from one place, instead of from each of them.
 */
function drawGame(): void {
  if (!game || !entry) return;
  const patch = screenElement.dataset.game === "restaurant-arena" ? updateRestaurantArena : undefined;
  if (!patch?.(game)) renderGameScreen();
  else setPersonalBest();
  if (!gameEnded && game.isOver()) endGame(game.hasWon() ? "won" : "lost");
  if (gameEnded) renderGameOver();
  scheduleClock();
}

// ── The shift ─────────────────────────────────────────────────────────
//
// One run at a time, described by four things: the game, the variation, the
// seed, and the accepted actions. That is exactly the `SavedGame` record, so
// resuming is a rebuild rather than a snapshot restore — see persistence.ts.

/** Every action attributed the same way, on the live path and the rebuild path. */
function actorFor(action: string): TraceActor {
  return action === "tick" || action === "bot_move" ? "environment" : "human";
}

/** Whose save this is. Preview mode has no account, and stores under `""`. */
function saveOwnerId(): string {
  return signedInUser()?.id ?? "";
}

/**
 * A seed for a brand-new run, never `exclude`. Restart means "start over with
 * a new run", not "replay the same one" (README), and a coin-flip that happens
 * to land on the replaced seed would silently make it the latter.
 */
function freshSeed(exclude?: number): number {
  for (let attempt = 0; attempt < 8; attempt++) {
    const seed = Math.floor(Math.random() * 0x7fff_ffff);
    if (seed !== exclude) return seed;
  }
  return ((exclude ?? 0) + 1) % 0x7fff_ffff;
}

/** Writes the run's journal so the next launch can rebuild it action by action. */
function persistRun(): void {
  if (!entry || !game || replaying) return;
  const record: SavedGame = {
    schemaVersion: 1,
    ownerId: saveOwnerId(),
    gameId: entry.id,
    gameVersion: entry.version,
    variationId: runVariationId,
    seed: runSeed,
    actions: runActions,
  };
  saveGame(record);
  // The menu's Resume button reads this, so it has to track the live run
  // rather than only what was on disk at boot.
  savedGame = record;
}

function cancelTick(): void {
  if (tickTimer !== undefined) window.clearTimeout(tickTimer);
  tickTimer = undefined;
}

/**
 * Arms whichever clock this shift runs on, or holds both.
 *
 * `tickMs()` is the single gate: the engine returns 0 while the sim is
 * unstarted, paused by the player, sitting on an open decision, or over. That
 * has to hold the live crew too — an orchestrator steps the engine itself, so
 * without this a shift the player paused would keep serving tables.
 */
function scheduleClock(): void {
  cancelTick();
  if (!game || screen !== "game" || gameEnded || replaying) return;
  const cadence = game.tickMs?.() ?? 0;
