// ── Host events ───────────────────────────────────────────────────────
//
// Rust dispatches these into the webview with `window.eval`. They are bound at
// module scope so a launch that arrives while boot is still reading settings is
// held rather than dropped.

window.addEventListener("gamepigeon:launch", (event) => {
  const detail = (event as CustomEvent<{ game?: unknown; variation?: unknown }>).detail;
  const gameId = typeof detail?.game === "string" ? detail.game : null;
  if (!gameId) return;
  const variationId = typeof detail?.variation === "string" ? detail.variation : undefined;
  // Nothing launches over the gate: there is no account to score the run for.
  if (screen === "gate") {
    pendingLaunch = { gameId, ...(variationId ? { variationId } : {}) };
    return;
  }
  launchById(gameId, variationId);
});

window.addEventListener("gamepigeon:pause", () => {
  // The `Stop` hook fires at every turn boundary, with or without a shift on
  // screen; `shouldPauseForAgent` is the one place that decides whether this
  // one is an interruption. Rust shows and focuses the window either way.
  if (!shouldPauseForAgent({
    inGame: screen === "game" && !gameEnded,
    autoPauseOnStop: settings.autoPauseOnStop,
    alreadyPaused: pauseState.paused,
  })) return;
  pauseRun("agent-stop");
});

window.addEventListener("gamepigeon:resume", () => {
  // The agent is working again, which is exactly when there is time to play:
  // open the floor back up and hand the shift back.
  if (windowMode === "pill") restoreFromPill();
  resumeRun();
});

window.addEventListener("gamepigeon:reset", () => {
  // A new session must never land mid-shift (README) — but this is the setting
  // the player turns off when they would rather it did.
  if (!settings.resetOnNewSession || screen === "gate") return;
  if (screen === "game") {
    // Ending a shift this way keeps the save, so the run is still resumable.
    leaveToMenu();
    return;
  }
  setDialog(null);
  screen = "menu";
  drawMenu();
});

window.addEventListener("gamepigeon:auth-success", (event) => {
  const detail = (event as CustomEvent<{ email?: unknown }>).detail;
  clearSignInPending();
  // The event carries only the address; Rust has already written the session,
  // so the account id — which scopes the save — is read back from disk.
  void loadAuthSession().then((stored) => {
    const user = stored ?? (typeof detail?.email === "string" ? { id: "", email: detail.email } : null);
    if (!user) {
      setSignInStatus("error", "Signed in, but the session could not be read. Try again.");
      return;
    }
    const saved = loadSavedGame();
    savedGame = saved?.ownerId === user.id ? saved : undefined;
    unlockTui(user);
    void invoke<string | null>("read_sync_error").then(setSyncError).catch(() => undefined);
    refreshLocalScores();
    recoverTraces();
    openInitialScreen(new URLSearchParams(window.location.search));
  });
});

window.addEventListener("gamepigeon:auth-error", (event) => {
  const detail = (event as CustomEvent<unknown>).detail;
  clearSignInPending();
  setSignInStatus("error", typeof detail === "string" && detail ? detail : "Sign-in failed. Try again.");
});

window.addEventListener("gamepigeon:sync-error", (event) => {
  const detail = (event as CustomEvent<unknown>).detail;
  setSyncError(typeof detail === "string" && detail ? detail : "Cloud sync is paused.");
});

window.addEventListener("gamepigeon:sync-success", () => setSyncError(null));

window.addEventListener("beforeunload", () => {
  // The run itself already survives in its `SavedGame` record; what has to be
  // handed over now is the recording, since a closing webview gets no turn to
  // seal it. Anything left behind is recovered as `client_closed` next launch.
  parkRunForRecovery();
});

bindUpdateBanner();
void refreshUpdateBanner();

