import { describe, expect, test } from "bun:test";
import {
  RUNNING,
  pausePromptTitle,
  pausedFor,
  shouldPauseForAgent,
  showsPausePrompt,
} from "./pause-state.js";

describe("agent-stop pauses", () => {
  const inGame = { inGame: true, autoPauseOnStop: true, alreadyPaused: false };

  test("interrupts a running shift when the player asked for it", () => {
    expect(shouldPauseForAgent(inGame)).toBe(true);
  });

  test("leaves the shift alone when auto-pause is off", () => {
    // Rust shows and focuses the window before dispatching either way, which
    // is the whole point of the preference: the overlay still comes forward,
    // it just doesn't take the shift away from whoever is mid-service.
    expect(shouldPauseForAgent({ ...inGame, autoPauseOnStop: false })).toBe(false);
  });

  test("ignores a stop with no shift on screen", () => {
    // The Stop hook fires at every turn boundary, including while the player
    // is sitting on the menu, the gate, or a finished shift.
    expect(shouldPauseForAgent({ ...inGame, inGame: false })).toBe(false);
  });

  test("does not re-pause a shift that is already stopped", () => {
    // The first reason a shift stopped is the one the player has to answer;
    // a second stop must not overwrite it.
    expect(shouldPauseForAgent({ ...inGame, alreadyPaused: true })).toBe(false);
  });
});

describe("pause state", () => {
  test("RUNNING carries no trigger", () => {
    expect(RUNNING).toEqual({ paused: false, trigger: null });
  });

  test("only an agent stop puts a card on screen", () => {
    // A minimized shift has nowhere to show a card — the pill replaces the
    // entire arcade — so it pauses silently.
    expect(showsPausePrompt(pausedFor("agent-stop"))).toBe(true);
    expect(showsPausePrompt(pausedFor("minimized"))).toBe(false);
    expect(showsPausePrompt(RUNNING)).toBe(false);
  });

  test("the card names what stopped the shift", () => {
    // Which is also what the player has to decide about: the agent is waiting
    // on them, or it isn't.
    expect(pausePromptTitle(pausedFor("agent-stop"))).toBe("Your agent needs you");
    expect(pausePromptTitle(pausedFor("minimized"))).toBe("Paused");
    expect(pausePromptTitle(RUNNING)).toBe("Paused");
  });
});

