import { describe, expect, test } from "bun:test";
import { REGISTRY } from "../src/games/registry.js";
import {
  clearSavedGame,
  loadSavedGame,
  restoreGame,
  saveGame,
  type SavedGame,
} from "./persistence.js";

function memoryStorage(): Storage & { store: Map<string, string> } {
  const store = new Map<string, string>();
  return {
    store,
    get length() {
      return store.size;
    },
    clear: () => store.clear(),
    getItem: (key: string) => store.get(key) ?? null,
    key: (index: number) => [...store.keys()][index] ?? null,
    removeItem: (key: string) => void store.delete(key),
    setItem: (key: string, value: string) => void store.set(key, value),
  } as unknown as Storage & { store: Map<string, string> };
}

/** A quota-exceeded or blocked store, which is a normal browser state. */
function brokenStorage(): Storage {
  return {
    length: 0,
    clear: () => {},
    getItem: () => {
      throw new Error("blocked");
    },
    key: () => null,
    removeItem: () => {
      throw new Error("blocked");
    },
    setItem: () => {
      throw new Error("quota exceeded");
    },
  } as unknown as Storage;
}

const entry = REGISTRY[0]!;
const variation = entry.variations[0]!;

/** Play a real run so the journal under test is one the engine actually produced. */
function playRun(seed: number, script: readonly string[]) {
  const game = entry.create!(variation.id);
  game.reset(seed);
  const actions: string[] = [];
  for (const action of script) {
    if (game.step(action).moved) actions.push(action);
  }
  return { game, actions };
}

function record(overrides: Partial<SavedGame> = {}): SavedGame {
  return {
    schemaVersion: 1,
    ownerId: "user_1",
    gameId: entry.id,
    gameVersion: entry.version,
    variationId: variation.id,
    seed: 4242,
    actions: [],
    ...overrides,
  };
}

describe("the active-game record", () => {
  test("round-trips through the store", () => {
    const storage = memoryStorage();
    const saved = record({ actions: ["sim_toggle", "tick"] });
    saveGame(saved, storage);
    expect(loadSavedGame(storage)).toEqual(saved);
  });

  test("keeps exactly one record, whatever the run before it was", () => {
    const storage = memoryStorage();
    saveGame(record({ seed: 1 }), storage);
    saveGame(record({ seed: 2 }), storage);
    expect(storage.store.size).toBe(1);
    expect(loadSavedGame(storage)?.seed).toBe(2);
  });

  test("clearing drops it entirely", () => {
    const storage = memoryStorage();
    saveGame(record(), storage);
    clearSavedGame(storage);
    expect(loadSavedGame(storage)).toBeNull();
    expect(storage.store.size).toBe(0);
  });

  test("an absent record is not an error", () => {
    expect(loadSavedGame(memoryStorage())).toBeNull();
  });

  test("a blocked or full store never throws at the run", () => {
    // Losing the save is survivable; throwing mid-shift is not.
    expect(() => saveGame(record(), brokenStorage())).not.toThrow();
    expect(() => clearSavedGame(brokenStorage())).not.toThrow();
    expect(loadSavedGame(brokenStorage())).toBeNull();
  });

  test("rejects a record it could not replay", () => {
    const storage = memoryStorage();
    for (const broken of [
      { schemaVersion: 2 },
      { seed: 1.5 },
      { actions: ["tick", 7] },
      { gameId: 3 },
    ]) {
      storage.store.clear();
      storage.setItem(
        "gamepigeon.arcade.active-game.v1",
        JSON.stringify({ ...record(), ...broken }),
      );
      expect(loadSavedGame(storage)).toBeNull();
    }
  });

  test("ignores a stored value that is not a record at all", () => {
    const storage = memoryStorage();
    storage.setItem("gamepigeon.arcade.active-game.v1", "not json");
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("stops extending a run past the cap rather than storing a rejected record", () => {
    // What is already on disk is a valid prefix of the same seeded run, so the
    // next launch still resumes — just a little earlier than the player left.
    const storage = memoryStorage();
    const short = record({ actions: ["sim_toggle"] });
    saveGame(short, storage);
    saveGame(record({ actions: Array.from({ length: 50_001 }, () => "tick") }), storage);
    expect(loadSavedGame(storage)).toEqual(short);
  });
});

describe("rebuilding a stored run", () => {
  test("replays the journal back to the same shift", () => {
    const seed = 4242;
    const script = ["sim_toggle", "tick", "tick", "tick"];
    const played = playRun(seed, script);
    const restored = restoreGame(entry, record({ seed, actions: played.actions }));
    expect(restored).not.toBeNull();
    expect(restored!.actions).toEqual(played.actions);
    expect(restored!.game.score()).toBe(played.game.score());
    expect(restored!.game.state()).toEqual(played.game.state());
  });

  test("refuses a record from a different game or rules version", () => {
    // Replaying it would produce a different game than the one the record
    // claims to be, which is worse than offering no resume at all.
    expect(restoreGame(entry, record({ gameId: "something-else" }))).toBeNull();
    expect(restoreGame(entry, record({ gameVersion: "0" }))).toBeNull();
  });

  test("refuses a journal holding an action this build no longer accepts", () => {
    expect(restoreGame(entry, record({ actions: ["retired_action"] }))).toBeNull();
  });

  test("an empty journal restores the run at its opening state", () => {
    const restored = restoreGame(entry, record({ actions: [] }));
    const fresh = entry.create!(variation.id);
    fresh.reset(4242);
    expect(restored).not.toBeNull();
    expect(restored!.actions).toEqual([]);
    expect(restored!.game.state()).toEqual(fresh.state());
  });
});

