import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import {
  COMPACT_SIZE,
  EXPANDED_SIZE,
  MIN_SIZE,
  PILL_SIZE,
  floorSize,
} from "./tauri-bridge.js";

describe("overlay frames", () => {
  test("are the sizes README publishes", () => {
    expect(COMPACT_SIZE).toEqual({ width: 600, height: 850 });
    expect(EXPANDED_SIZE).toEqual({ width: 830, height: 900 });
    expect(PILL_SIZE).toEqual({ width: 144, height: 48 });
    expect(MIN_SIZE).toEqual({ width: 500, height: 700 });
  });

  test("README's window-sizes table still quotes them", () => {
    // The table names this module as the source of the numbers, so a change
    // here that skips the table would make the docs quietly wrong.
    const readme = readFileSync(join(import.meta.dir, "..", "README.md"), "utf8");
    for (const [size, label] of [
      [COMPACT_SIZE, "compact"],
      [EXPANDED_SIZE, "expanded"],
      [PILL_SIZE, "pill"],
      [MIN_SIZE, "minimum"],
    ] as const) {
      expect(readme, `README is missing the ${label} frame`)
        .toContain(`${size.width} × ${size.height}`);
    }
  });

  test("the browser preview frames the same compact size", () => {
    const preview = readFileSync(join(import.meta.dir, "preview.html"), "utf8");
    expect(preview).toContain(`{ width: ${COMPACT_SIZE.width}, height: ${COMPACT_SIZE.height} }`);
  });

  test("only the pill sits below the floor's minimum", () => {
    // Which is exactly why `applyOverlaySize` writes the minimum before the
    // size: a minimum still set to the floor's would clamp 144 × 48 back up.
    expect(PILL_SIZE.width).toBeLessThan(MIN_SIZE.width);
    expect(PILL_SIZE.height).toBeLessThan(MIN_SIZE.height);
    for (const size of [COMPACT_SIZE, EXPANDED_SIZE]) {
      expect(size.width).toBeGreaterThanOrEqual(MIN_SIZE.width);
      expect(size.height).toBeGreaterThanOrEqual(MIN_SIZE.height);
    }
  });
});

describe("floorSize", () => {
  test("maps each size preference to its frame", () => {
    expect(floorSize("compact")).toEqual(COMPACT_SIZE);
    expect(floorSize("expanded")).toEqual(EXPANDED_SIZE);
  });

  test("never returns a frame below the minimum", () => {
    for (const mode of ["compact", "expanded"] as const) {
      const size = floorSize(mode);
      expect(size.width).toBeGreaterThanOrEqual(MIN_SIZE.width);
      expect(size.height).toBeGreaterThanOrEqual(MIN_SIZE.height);
    }
  });
});

