import { Window } from "happy-dom";
import { readFileSync } from "node:fs";

const html = readFileSync("/app/overlay/dist/index.html", "utf8");
const win = new Window({ url: "http://localhost/?scores=demo" });
win.document.write(html);
// @ts-expect-error test shim
globalThis.window = win;
for (const key of ["document", "localStorage", "navigator", "CustomEvent", "Event", "HTMLElement", "HTMLInputElement", "HTMLSelectElement", "Node", "Blob", "URL", "requestAnimationFrame", "getComputedStyle", "Image", "performance"] as const) {
  // @ts-expect-error test shim
  globalThis[key] = win[key];
}
// @ts-expect-error test shim
globalThis.__APP_VERSION__ = "0.0.0-smoke";

await import("/app/overlay/app.ts");
await new Promise((r) => setTimeout(r, 400));

const doc = win.document;
console.log("screen:", doc.querySelector("#screen")?.getAttribute("data-screen"));
console.log("resize label:", doc.querySelector("#resize")?.textContent);

// Launch a run through the deep-link path the host uses.
win.dispatchEvent(new win.CustomEvent("gamepigeon:launch", { detail: { game: "restaurant-arena", variation: "dinner-rush" } }));
await new Promise((r) => setTimeout(r, 300));
console.log("after launch:", doc.querySelector("#screen")?.getAttribute("data-screen"), doc.querySelector("#screen")?.getAttribute("data-game"));
console.log("saved:", win.localStorage.getItem("gamepigeon.arcade.active-game.v1"));

// Agent stop -> paused card.
win.dispatchEvent(new win.Event("gamepigeon:pause"));
await new Promise((r) => setTimeout(r, 50));
console.log("pause card hidden:", doc.querySelector("#return-prompt")?.hasAttribute("hidden"), "title:", doc.querySelector("#return-title")?.textContent);

// Back to coding -> pill.
(doc.querySelector("#return-code") as any).click();
await new Promise((r) => setTimeout(r, 50));
console.log("body mode:", doc.body.getAttribute("data-mode"));

// Reopen.
(doc.querySelector("#pill") as any).click();
await new Promise((r) => setTimeout(r, 50));
console.log("body mode after restore:", doc.body.getAttribute("data-mode"), "pause card hidden:", doc.querySelector("#return-prompt")?.hasAttribute("hidden"));

// How to Play from the menu path.
(doc.querySelector("#how-to-play-close") as any)?.click();
(doc.querySelector("#resize") as any).click();
console.log("resize label after toggle:", doc.querySelector("#resize")?.textContent);

// Restart mid-run: new seed, save discarded then rewritten.
const before = JSON.parse(win.localStorage.getItem("gamepigeon.arcade.active-game.v1") ?? "null");
win.dispatchEvent(new win.Event("gamepigeon:reset"));
await new Promise((r) => setTimeout(r, 100));
console.log("after reset:", doc.querySelector("#screen")?.getAttribute("data-screen"));
console.log("resume button present:", Boolean(doc.querySelector("[data-resume]")));
console.log("seed before:", before?.seed);

