  return isTauri() ? new TauriLogicalSize(width, height) : new LogicalSize(width, height);
}

/**
 * The browser stand-in is structural, and the preview's `setSize` only ever
 * reads `width`/`height` off it — so the one place that difference exists is
 * here, rather than at every call site.
 */
function windowSize(size: OverlaySize): TauriLogicalSize {
  return overlayLogicalSize(size.width, size.height) as TauriLogicalSize;
}

/**
 * Resizes the overlay frame. The minimum is written first, always: collapsing
 * to the pill goes *below* the floor minimum, so a minimum still set to the
 * floor's would clamp the pill straight back up to 500 × 700.
 */
export async function applyOverlaySize(size: OverlaySize, minSize: OverlaySize = size): Promise<void> {
  const handle = getOverlayWindow();
  await handle.setMinSize(windowSize(minSize));
  await handle.setSize(windowSize(size));
}

