toolUseResult.originalFile:
/**
 * End-to-end cover for the session lifecycle: launching a run, pausing for the
 * agent and resuming, restarting mid-run, ending a shift, and the pill /
 * resize window chrome — driven through the real `app.ts` against a DOM.
 *
 * Assertions are on observable state (the screen dataset, `body[data-mode]`,
 * dialog `hidden`, the saved-game record, the frame sizes the preview bridge
 * announces) rather than on the tick clock: the arena's cadence is 3–4.5 s per
 * tick, so waiting for one would make this the slowest file in the suite for
 * no extra confidence.
 */

import { beforeAll, describe, expect, mock, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { COMPACT_SIZE, EXPANDED_SIZE, PILL_SIZE, PREVIEW_RESIZE_MESSAGE } from "./tauri-bridge.js";

const SAVE_KEY = "gamepigeon.arcade.active-game.v1";

interface SavedRecord {
  gameId: string;
  variationId: string;
  seed: number;
  actions: string[];
}

// Phaser wants a real WebGL/2D canvas, which no DOM shim here can supply — and
// the arena canvas is not what this file is testing. The stub keeps the mount
// contract (`render`/`setWorkerStatus`/`destroy`) and records the UI callback
// so the on-canvas menu/restart/help buttons can still be exercised.
let sceneUi: ((action: "menu" | "restart" | "help") => void) | undefined;
let mountCount = 0;
mock.module("./restaurant-arena-scene.js", () => ({
  mountRestaurantArenaScene: (
    _parent: HTMLElement,
    _state: unknown,
    _onAction: (action: string) => void,
    onUi: (action: "menu" | "restart" | "help") => void,
  ) => {
    mountCount += 1;
    sceneUi = onUi;
    return { render: () => {}, setWorkerStatus: () => {}, destroy: () => {} };
  },
}));

let win: import("happy-dom").Window;
let doc: Document;
/** Every frame the overlay has asked for, in order, via the preview bridge. */
const frames: { width: number; height: number }[] = [];

const settle = (ms = 30) => new Promise((resolve) => setTimeout(resolve, ms));

function el(selector: string): HTMLElement {
  const found = doc.querySelector<HTMLElement>(selector);
  if (!found) throw new Error(`missing ${selector}`);
  return found;
}

function screenName(): string | undefined {
  return el("#screen").dataset.screen;
}

function visible(selector: string): boolean {
  return !el(selector).hasAttribute("hidden");
}

function saved(): SavedRecord | null {
  const raw = win.localStorage.getItem(SAVE_KEY);
  return raw ? (JSON.parse(raw) as SavedRecord) : null;
}

function lastFrame(): { width: number; height: number } | undefined {
  return frames.at(-1);
}

async function click(selector: string): Promise<void> {
  el(selector).click();
  await settle();
}

async function press(key: string): Promise<void> {
  // Dispatched on an element, as a browser would: the handler reads
  // `event.target.matches(...)` to ignore keys typed into a field.
  const target = (doc.activeElement as HTMLElement | null) ?? doc.body;
  target.dispatchEvent(new win.KeyboardEvent("keydown", { key, bubbles: true, cancelable: true }));
  await settle();
}

async function host(name: string, detail?: unknown): Promise<void> {
  win.dispatchEvent(new win.CustomEvent(name, { detail }));
  await settle();
}

beforeAll(async () => {
  const { Window } = await import("happy-dom");
  win = new Window({ url: "http://localhost/" });
  win.document.write(readFileSync(join(import.meta.dir, "dist", "index.html"), "utf8"));
  doc = win.document as unknown as Document;

  // `app.ts` is written against a browser, so the globals it reaches for have
  // to exist before it is imported — module top level binds `document`,
  // `#screen` and the window listeners immediately.
  Object.defineProperty(globalThis, "window", { value: win, configurable: true, writable: true });
  const adopt = (key: string) => {
    try {
      (globalThis as Record<string, unknown>)[key] = (win as unknown as Record<string, unknown>)[key];
    } catch {
      /* a read-only global the shim cannot replace, and does not need to */
    }
  };
  for (const key of Object.getOwnPropertyNames(win)) if (!(key in globalThis)) adopt(key);
  // Bun has natives for several of these, and a native `CustomEvent` cannot be
  // dispatched on a happy-dom target ("parameter 1 is not of type 'Event'") —
  // so the DOM's own classes have to win, not merely fill the gaps.
  for (const key of [
    "document", "location", "localStorage", "sessionStorage", "navigator", "history",
    "EventTarget", "Event", "CustomEvent", "KeyboardEvent", "MouseEvent", "PointerEvent",
    "FocusEvent", "InputEvent", "MessageEvent", "Node", "Element", "HTMLElement",
    "HTMLInputElement", "HTMLSelectElement", "HTMLButtonElement", "Blob", "URL",
    "requestAnimationFrame", "cancelAnimationFrame", "getComputedStyle", "matchMedia",
  ]) adopt(key);
  (globalThis as Record<string, unknown>).__APP_VERSION__ = "0.0.0-test";
  win.addEventListener(PREVIEW_RESIZE_MESSAGE, (event) => {
    const detail = (event as CustomEvent<{ width: number; height: number }>).detail;
    frames.push({ width: detail.width, height: detail.height });
  });

  win.localStorage.clear();
  await import("./app.js");
  await settle(150);
});

describe("overlay session", () => {
  test("boots to the menu at the compact frame", () => {
    expect(screenName()).toBe("menu");
    expect(lastFrame()).toEqual(COMPACT_SIZE);
    expect(el("#resize").getAttribute("aria-label")).toBe("Expand overlay");
    expect(doc.body.dataset.mode).toBeUndefined();
  });

  test("the host launch event starts a run and journals it", async () => {
    await host("gamepigeon:launch", { game: "restaurant-arena", variation: "dinner-rush" });

    expect(screenName()).toBe("game");
    expect(el("#screen").dataset.game).toBe("restaurant-arena");
    const record = saved();
    expect(record?.gameId).toBe("restaurant-arena");
    expect(record?.variationId).toBe("dinner-rush");
    expect(record?.actions).toEqual([]);
    expect(record?.seed).toBeGreaterThan(0);
  });

  test("an accepted action is appended to the journal", async () => {
    await press(" "); // `space` → sim_toggle, which starts the shift clock
    expect(saved()?.actions).toEqual(["sim_toggle"]);
  });

  test("the agent stopping raises the pause prompt", async () => {
    await host("gamepigeon:pause");

    expect(visible("#return-prompt")).toBe(true);
    expect(el("#return-title").textContent).toBe("Your agent needs you");
  });

  test("How to Play opens over the pause prompt and returns to it", async () => {
    await click("#how-to-play-from-pause");
    expect(visible("#how-to-play")).toBe(true);
    expect(visible("#return-prompt")).toBe(false);

    await click("#how-to-play-close");
    expect(visible("#how-to-play")).toBe(false);
    expect(visible("#return-prompt")).toBe(true);
  });

  test("back to coding minimizes to the pill, and the pill restores", async () => {
    await click("#return-code");
    expect(doc.body.dataset.mode).toBe("pill");
    expect(lastFrame()).toEqual(PILL_SIZE);
    expect(visible("#return-prompt")).toBe(false);

    await click("#pill");
    expect(doc.body.dataset.mode).toBeUndefined();
    expect(lastFrame()).toEqual(COMPACT_SIZE);
    // The pill's own pause is lifted on restore, so the prompt stays down.
    expect(visible("#return-prompt")).toBe(false);
    expect(screenName()).toBe("game");
  });

  test("the resize toggle swaps between the two floor frames", async () => {
    await click("#resize");
    expect(lastFrame()).toEqual(EXPANDED_SIZE);
    expect(el("#resize").getAttribute("aria-label")).toBe("Compact overlay");

    await click("#resize");
    expect(lastFrame()).toEqual(COMPACT_SIZE);
    expect(el("#resize").getAttribute("aria-label")).toBe("Expand overlay");
  });

  test("restarting mid-run re-seeds the shift and clears the old journal", async () => {
    const before = saved();
    const mountsBefore = mountCount;

    await press("r");

    const after = saved();
    expect(after?.seed).not.toBe(before?.seed);
    expect(after?.variationId).toBe("dinner-rush");
    expect(after?.actions).toEqual([]);
    expect(screenName()).toBe("game");
    expect(mountCount).toBeGreaterThan(mountsBefore);
  });

  test("the on-canvas restart button restarts too", async () => {
    const before = saved();
    sceneUi?.("restart");
    await settle();
    expect(saved()?.seed).not.toBe(before?.seed);
  });

  test("ending the shift returns to the menu and offers the run back", async () => {
    await press(" "); // a move worth resuming
    const abandoned = saved();
    expect(abandoned?.actions).toEqual(["sim_toggle"]);

    sceneUi?.("menu");
    await settle();

    expect(screenName()).toBe("menu");
    // An abandoned shift keeps its record, so the menu can offer it back.
    expect(saved()).toEqual(abandoned);
    expect(doc.querySelector("[data-resume]")).not.toBeNull();
  });

  test("the menu's resume button rebuilds the saved shift", async () => {
    const record = saved();

    await click("[data-resume]");

    expect(screenName()).toBe("game");
    expect(el("#screen").dataset.game).toBe("restaurant-arena");
    // Same seed, same journal: this is the shift that was left, not a new one.
    expect(saved()).toEqual(record);
  });

  test("Escape from the floor minimizes, and Enter on the pill restores", async () => {
    await press("Escape");
    expect(doc.body.dataset.mode).toBe("pill");

    await press("Enter");
    expect(doc.body.dataset.mode).toBeUndefined();
    expect(screenName()).toBe("game");
  });

  test("a host reset ends the shift back at the menu", async () => {
    await host("gamepigeon:reset");
    expect(screenName()).toBe("menu");
    expect(visible("#return-prompt")).toBe(false);
  });
});

